+/// The name of the cookie a browser paired with this host keeps its
+/// token in. Cookies ignore ports, so two instances on one Mac share a
+/// browser's jar for the address; the server id keeps their cookies
+/// apart, and it survives a key rotation. `__Host-` makes the browser
+/// refuse it unless it is `Secure`, `Path=/` and has no `Domain`.
+#[must_use]
+pub fn token_cookie_name(server_id: Uuid) -> String {
+    format!("__Host-sb-{server_id}")
+}
