// Switchboard's page on the remote port. It speaks the protocol a
// native client speaks (docs/remote-client.md) over the page's own
// origin: the host keeps the token in an HttpOnly cookie this script
// never sees, so what the page keeps is public (the host's id, key hash
// and name), and every text from the host reaches the page through
// `textContent` only, never as markup.
'use strict';

// Every path the page calls, in one table so a test on the host can
// check that each one is served. `{id}` is a project or session id.
const API = {
  info: '/api/v1/info',
  pair: '/api/v1/pair',
  me: '/api/v1/me',
  projects: '/api/v1/projects',
  sessions: '/api/v1/projects/{id}/sessions',
  waiting: '/api/v1/waiting',
  lastResponse: '/api/v1/sessions/{id}/last-response',
  screen: '/api/v1/sessions/{id}/screen',
  send: '/api/v1/sessions/{id}/send',
  events: '/api/v1/events',
};

const STORE_KEY = 'switchboard';
// The poll carries the page on every browser; when the events socket
// is up, a change arrives at once and the poll only backs it up.
const POLL_MS = 3000;
const POLL_WITH_SOCKET_MS = 20000;
const RETRY_FIRST_MS = 5000;
const RETRY_LAST_MS = 60000;

