const RETRY_LAST_MS = 60000;

// --- pure parts, tested with `node --test web/app.test.js`

function apiPath(name, id) {
  return API[name].replace('{id}', encodeURIComponent(id || ''));
}

// The invite's code, key and server id from the URL's fragment, or
// null when any is missing.
function parseFragment(hash) {
  const values = {};
  for (const pair of String(hash || '').replace(/^#/, '').split('&')) {
    const at = pair.indexOf('=');
    if (at < 1) continue;
    try {
      values[decodeURIComponent(pair.slice(0, at))] = decodeURIComponent(pair.slice(at + 1));
    } catch (_) {
      return null;
    }
  }
  if (!values.code || !values.key || !values.id) return null;
  return { code: values.code, key: values.key, id: values.id };
}

// "Safari on iPhone": what the host's device list shows for this
// browser. An iPad asking for the desktop site says Macintosh, and only
// its touch points tell it from a Mac.
function deviceName(ua, touchPoints) {
  let browser = 'Safari';
  if (/Edg(e|iOS|A)?\//.test(ua)) browser = 'Edge';
  else if (/(Chrome|CriOS)\//.test(ua)) browser = 'Chrome';
  else if (/(Firefox|FxiOS)\//.test(ua)) browser = 'Firefox';
  let device = null;
  if (/iPhone/.test(ua)) device = 'iPhone';
  else if (/iPad/.test(ua) || (/Macintosh/.test(ua) && touchPoints > 1)) device = 'iPad';
  else if (/Android/.test(ua)) device = 'Android';
  else if (/Macintosh|Mac OS X/.test(ua)) device = 'Mac';
  else if (/Windows/.test(ua)) device = 'Windows';
  else if (/Linux/.test(ua)) device = 'Linux';
  return device ? browser + ' on ' + device : 'Browser';
}

// What a 401 means. The host answers a revoked token and an unknown one
// alike, so the page asks `/info`, which anyone may read: the same id
// and key as when it paired say this device was removed; another says
// the host's identity changed; no answer says the host is out of reach.
function unauthorizedState(stored, info) {
  if (!stored) return 'unpaired';
  if (!info) return 'unreachable';
  if (info.server_id === stored.server_id && info.spki_sha256 === stored.spki_sha256) {
    return 'removed';
  }
  return 'changed';
}

const STATE_TEXT = {
  unpaired: 'Not paired. On the Mac, open Remote devices, allow pairing, and scan its code.',
  unreachable: "Can't reach the host.",
  removed: 'This device was removed on the host. Pair again.',
  changed: "This host's identity changed. Pair again.",
};

const PAIR_ERRORS = {
  pairing_closed: 'Pairing is not open on the Mac. Open it again and scan the new code.',
  wrong_code: 'The code did not match. Scan the code the Mac shows now.',
  wrong_key: 'This is not the Switchboard whose code was scanned. Nothing was paired.',
  rate_limited: 'Too many attempts. Wait a minute and scan again.',
};

// Whether a reply should replace what the page holds (§4.4): a reply
// from another epoch (the host restarted) always does; within one, an
// older revision never does.
function isNewer(held, reply) {
  if (!held) return true;
  if (held.epoch !== reply.epoch) return true;
  return reply.revision >= held.revision;
}

// Whether the host moved since `held` was read.
function moved(held, reply) {
  return !held || held.epoch !== reply.epoch || held.revision !== reply.revision;
}

// Projects with a waiting session first, waiting sessions first within
// each; otherwise the host's order.
function orderGroups(projects, sessionsByProject) {
  const waitingFirst = (items, isWaiting) =>
    items
      .map((item, at) => ({ item, at }))
      .sort((a, b) => Number(isWaiting(b.item)) - Number(isWaiting(a.item)) || a.at - b.at)
